        if c is not None:
            return [c], tier
        if tier == "unknown":
            return [], tier
        pos = SLOT_POS[slot]
        anchored = {g: a for g, a in self.reg.anchors.items() if a[1] == pos}
        tb = wn.morphy(token, pos) or token
